package local.wallpanel.app;
import android.app.Activity;
import android.content.pm.PackageManager;
import android.os.*;
import android.text.InputType;
import android.view.View;
import android.widget.*;
/** Private administrator SIP configuration; the optional module is shared with main setup. */
public final class SipSettingsActivity extends Activity {
    private Spinner stationBrand;private SipStore store;private LinearLayout page;private EditText server,serverPort,user,auth,password,address,port,rtp,timeout,volume,ringVolume,videoUrl,doorServer,doorUser,doorPassword;private CheckBox enabled,auto,aec,ns,agc,ringtone,video,doorOne,doorTwo;private TextView status;private final Handler main=new Handler();
    private EditText field(String name,String text,int type){TextView label=new TextView(this);label.setText(name);label.setTextSize(16);page.addView(label);EditText edit=new EditText(this);edit.setSingleLine(true);edit.setInputType(type);edit.setText(text);page.addView(edit);return edit;}
    private CheckBox check(String label,boolean value){CheckBox box=new CheckBox(this);box.setText(label);box.setChecked(value);page.addView(box);return box;}
    @Override public void onCreate(Bundle b){super.onCreate(b);store=new SipStore(this);ScrollView scroll=new ScrollView(this);page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(24,20,24,32);scroll.addView(page);setContentView(scroll);
        try{boolean imported=store.importPending();SipConfig c=store.load();TextView title=new TextView(this);title.setText("SIP intercom");title.setTextSize(26);page.addView(title);status=new TextView(this);status.setTextSize(17);status.setPadding(0,12,0,16);page.addView(status);enabled=check("Enable SIP intercom on this panel",store.enabled());int text=InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS;
            server=field("SIP server",c.server,text);serverPort=field("Server port",String.valueOf(c.serverPort),InputType.TYPE_CLASS_NUMBER);user=field("Extension / SIP user",c.user,text);auth=field("Authentication user (blank uses extension)",c.authUser,text);password=field("SIP password",c.password,InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);address=field("Local IPv4 override (Auto network only; blank recommended)",c.localAddress,text);port=field("Local SIP port",String.valueOf(c.sipPort),InputType.TYPE_CLASS_NUMBER);rtp=field("Local RTP port (even)",String.valueOf(c.rtpPort),InputType.TYPE_CLASS_NUMBER);auto=check("Automatically answer incoming calls",c.autoAnswer);timeout=field("Ring timeout in seconds",String.valueOf(c.ringSeconds),InputType.TYPE_CLASS_NUMBER);volume=field("Call volume percent",String.valueOf(c.volume),InputType.TYPE_CLASS_NUMBER);ringtone=check("Play incoming call chime",c.ringtoneEnabled);ringVolume=field("Ringing volume percent (separate from call volume)",String.valueOf(c.ringVolume),InputType.TYPE_CLASS_NUMBER);video=check("Show RTSP video during incoming and active calls",c.videoEnabled);videoUrl=field("RTSP URL (include camera login if required)",c.videoUrl,InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);TextView hint=new TextView(this);hint.setText("Video is muted. Use an H.264 camera stream. Credentials in the URL are encrypted with SIP settings.");page.addView(hint);aec=check("Acoustic echo cancellation",c.aec);ns=check("Noise suppression",c.noiseSuppressor);agc=check("Automatic microphone gain",c.gainControl);
            TextView brandLabel=new TextView(this);brandLabel.setText("Door station brand");page.addView(brandLabel);stationBrand=new Spinner(this);ArrayAdapter<String> brandAdapter=new ArrayAdapter<String>(this,android.R.layout.simple_spinner_item,SipConfig.stationBrandNames());brandAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);stationBrand.setAdapter(brandAdapter);stationBrand.setSelection(c.stationBrand.equals("hikvision")?1:0);page.addView(stationBrand);TextView brandHint=new TextView(this);brandHint.setText("Hikvision door controls use ISAPI. SIP audio and RTSP video are configured independently. Other brand adapters can be added later.");page.addView(brandHint);doorServer=field("Door station HTTP(S) address (no path)",c.doorServer,text);doorUser=field("Door station user",c.doorUser,text);doorPassword=field("Door station password",c.doorPassword,InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);doorOne=check("Enable Door 1 unlock button",c.doorOneEnabled);doorTwo=check("Enable Door 2 unlock button",c.doorTwoEnabled);Button save=new Button(this);save.setText("Save intercom settings");page.addView(save);save.setOnClickListener(new View.OnClickListener(){public void onClick(View v){save();}});Button permission=new Button(this);permission.setText("Grant microphone permission");page.addView(permission);permission.setOnClickListener(new View.OnClickListener(){public void onClick(View v){microphone();}});Button networks=new Button(this);networks.setText("Network assignments");page.addView(networks);networks.setOnClickListener(new View.OnClickListener(){public void onClick(View v){startActivity(new android.content.Intent(SipSettingsActivity.this,NetworkSettingsActivity.class));}});Button back=new Button(this);back.setText("Back to setup");page.addView(back);back.setOnClickListener(new View.OnClickListener(){public void onClick(View v){finish();}});if(imported)SipRuntime.reconcile(this);main.post(refresh);
        }catch(Exception failure){TextView error=new TextView(this);error.setText("Intercom settings could not be opened ("+failure.getClass().getSimpleName()+"). Existing settings were kept.");page.addView(error);}
    }
    private void microphone(){if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},52);else Toast.makeText(this,"Microphone permission is already granted",Toast.LENGTH_SHORT).show();}
    private void save(){try{SipConfig c=new SipConfig();c.server=server.getText().toString().trim();c.serverPort=Integer.parseInt(serverPort.getText().toString());c.user=user.getText().toString().trim();c.authUser=auth.getText().toString().trim();c.password=password.getText().toString();c.localAddress=address.getText().toString().trim();c.sipPort=Integer.parseInt(port.getText().toString());c.rtpPort=Integer.parseInt(rtp.getText().toString());c.ringSeconds=Integer.parseInt(timeout.getText().toString());c.volume=Integer.parseInt(volume.getText().toString());c.autoAnswer=auto.isChecked();c.aec=aec.isChecked();c.noiseSuppressor=ns.isChecked();c.gainControl=agc.isChecked();c.ringtoneEnabled=ringtone.isChecked();c.ringVolume=Integer.parseInt(ringVolume.getText().toString());c.videoEnabled=video.isChecked();c.videoUrl=videoUrl.getText().toString().trim();c.stationBrand=SipConfig.stationBrandIds()[stationBrand.getSelectedItemPosition()];c.doorServer=doorServer.getText().toString().trim();c.doorUser=doorUser.getText().toString().trim();c.doorPassword=doorPassword.getText().toString();c.doorOneEnabled=doorOne.isChecked();c.doorTwoEnabled=doorTwo.isChecked();c.validate();if(SipRuntime.inCall()&&!store.load().sameConnection(c))throw new IllegalArgumentException("End the call before changing SIP connection settings");store.save(c);store.enabled(enabled.isChecked());SipRuntime.reconcile(this);Toast.makeText(this,"Intercom settings saved",Toast.LENGTH_SHORT).show();if(enabled.isChecked()&&checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)microphone();}catch(Exception error){Toast.makeText(this,error.getMessage()==null?"Settings could not be saved":error.getMessage(),Toast.LENGTH_LONG).show();}}
    private final Runnable refresh=new Runnable(){public void run(){if(status!=null)status.setText(store.status());main.postDelayed(this,1000);}};
    @Override protected void onStop(){main.removeCallbacksAndMessages(null);super.onStop();if(new ConfigStore(this).locked())finish();}
    @Override protected void onResume(){super.onResume();main.removeCallbacksAndMessages(null);main.post(refresh);}
}
